perl -e '
use strict;
use warnings;
use File::Find;

my $internal = "/bench/repo/internal";
my $repo = "/bench/repo";

my @decls;
find({
  wanted => sub {
    return unless /\.go$/ && !/_test\.go$/;
    my $path = $File::Find::name;
    return unless $path =~ m{^\Q$internal\E};
    open my $fh, "<", $path or die $!;
    local $/;
    my $text = <$fh>;
    close $fh;
    my $pkg = "unknown";
    $pkg = $1 if $text =~ /^package\s+(\w+)/m;
    while ($text =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/mg) {
      my ($recv, $name) = ($1, $2);
      next if $name eq "init";
      my $pos = $-[0];
      my $line = 1 + (substr($text,0,$pos) =~ tr/\n//);
      push @decls, {pkg=>$pkg, name=>$name, path=>$path, recv=>$recv//"", line=>$line};
    }
  },
  no_chdir => 1,
}, $internal);

print "DECLS: ", scalar(@decls), "\n";
my %namecount;
$namecount{$_->{name}}++ for @decls;
print "DUPLICATE NAMES:\n";
for my $n (sort { $namecount{$b} <=> $namecount{$a} } keys %namecount) {
  print "  $n $namecount{$n}\n" if $namecount{$n} > 1;
}
print "ALL:\n";
for my $d (sort { $a->{pkg} cmp $b->{pkg} || $a->{name} cmp $b->{name} } @decls) {
  print "  $d->{pkg}.$d->{name} recv=[$d->{recv}] $d->{path}:$d->{line}\n";
}
'

