perl -e '
use strict;
use warnings;

# Load all go files (exclude proto/gen)
open my $lf, "<", "/tmp/all_go.txt" or die $!;
my @files = <$lf>; chomp @files;
close $lf;

# Also include tests? all_go.txt already has tests. proto/gen excluded.

my %file_text;
my %file_pkg;
my %file_is_test;
for my $path (@files) {
  open my $fh, "<", $path or die "$path: $!";
  my $text = do { local $/; <$fh> };
  close $fh;
  $file_text{$path} = $text;
  $file_pkg{$path} = ($text =~ /^package\s+(\w+)/m) ? $1 : "";
  $file_is_test{$path} = ($path =~ /_test\.go$/) ? 1 : 0;
}

# Load internal decls
open $lf, "<", "/tmp/internal_go.txt" or die $!;
my @internal = <$lf>; chomp @internal;
close $lf;

my @decls;
for my $path (@internal) {
  my $text = $file_text{$path} // die "missing $path";
  my $pkg = $file_pkg{$path};
  while ($text =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/mg) {
    my ($recv, $name) = ($1, $2);
    next if $name eq "init";
    my $pos = $-[0];
    my $line = 1 + (substr($text,0,$pos) =~ tr/\n//);
    push @decls, {pkg=>$pkg, name=>$name, path=>$path, recv=>$recv//"", line=>$line, is_method=>defined($recv)&&$recv ne ""};
  }
}

# Count call sites per declaration.
# For functions: same-pkg Name(  or  pkg.Name(
# For methods: .Name(
# Exclude the declaration line itself.
# Also exclude comments roughly by counting only after we strip line comments? Simple approach: count in file text.

sub count_matches {
  my ($text, $re) = @_;
  my $n = 0;
  $n++ while $text =~ /$re/g;
  return $n;
}

my @results;
for my $d (@decls) {
  my $name = $d->{name};
  my $pkg = $d->{pkg};
  my $prod = 0;
  my $test = 0;
  my $same_pkg_prod = 0;
  my $cross_prod = 0;
  for my $path (keys %file_text) {
    my $text = $file_text{$path};
    my $fpkg = $file_pkg{$path};
    my $n = 0;
    if ($d->{is_method}) {
      # method call: .Name(  or possibly Name( if promoted - skip
      $n = count_matches($text, qr/\.$name\s*\(/);
    } else {
      if ($fpkg eq $pkg) {
        # same package: Name( but not func Name( and not pkg.Name if different
        $n = count_matches($text, qr/(?<![\w.])$name\s*\(/);
        # subtract declarations
        $n -= count_matches($text, qr/^func\s+$name\s*\(/m);
        $n -= count_matches($text, qr/^func\s+\([^)]+\)\s+$name\s*\(/m);
      } else {
        $n = count_matches($text, qr/\b$pkg\.$name\s*\(/);
      }
    }
    $n = 0 if $n < 0;
    if ($file_is_test{$path}) {
      $test += $n;
    } else {
      $prod += $n;
      if ($fpkg eq $pkg) { $same_pkg_prod += $n; }
      else { $cross_prod += $n; }
    }
  }
  push @results, {d=>$d, prod=>$prod, test=>$test, total=>$prod+$test, same=>$same_pkg_prod, cross=>$cross_prod};
}

@results = sort { $b->{total} <=> $a->{total} || $b->{prod} <=> $a->{prod} } @results;
print "TOP 40 by total (prod+test):\n";
for my $i (0..39) {
  my $r = $results[$i];
  my $d = $r->{d};
  printf "%2d. %s.%s meth=%d prod=%d test=%d total=%d sameprod=%d crossprod=%d %s:%d\n",
    $i+1, $d->{pkg}, $d->{name}, $d->{is_method}?1:0, $r->{prod}, $r->{test}, $r->{total}, $r->{same}, $r->{cross}, $d->{path}, $d->{line};
}

print "\nTOP 20 by prod only:\n";
@results = sort { $b->{prod} <=> $a->{prod} } @results;
for my $i (0..19) {
  my $r = $results[$i];
  my $d = $r->{d};
  printf "%2d. %s.%s meth=%d prod=%d test=%d total=%d %s:%d\n",
    $i+1, $d->{pkg}, $d->{name}, $d->{is_method}?1:0, $r->{prod}, $r->{test}, $r->{total}, $d->{path}, $d->{line};
}
'

perl -e '
use strict;
use warnings;

open my $lf, "<", "/tmp/all_go.txt" or die $!;
my @files = <$lf>; chomp @files;
close $lf;

my %file_text; my %file_pkg; my %file_is_test;
for my $path (@files) {
  open my $fh, "<", $path or die "$path: $!";
  my $text = do { local $/; <$fh> };
  close $fh;
  $file_text{$path} = $text;
  $file_pkg{$path} = ($text =~ /^package\s+(\w+)/m) ? $1 : "";
  $file_is_test{$path} = ($path =~ /_test\.go$/) ? 1 : 0;
}

open $lf, "<", "/tmp/internal_go.txt" or die $!;
my @internal = <$lf>; chomp @internal;
close $lf;

my @decls;
for my $path (@internal) {
  my $text = $file_text{$path};
  my $pkg = $file_pkg{$path};
  while ($text =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/mg) {
    my ($recv, $name) = ($1, $2);
    next if $name eq "init";
    my $pos = $-[0];
    my $line = 1 + (substr($text,0,$pos) =~ tr/\n//);
    push @decls, {pkg=>$pkg, name=>$name, path=>$path, recv=>$recv//"", line=>$line, is_method=>defined($recv)&&$recv ne ""};
  }
}

sub count_matches {
  my ($text, $re) = @_;
  my $n = 0;
  $n++ while $text =~ /$re/g;
  return $n;
}

print "=== PACKAGE-LEVEL FUNCS (prod / test / total) ===\n";
my @funcs;
for my $d (@decls) {
  next if $d->{is_method};
  my $name = $d->{name};
  my $pkg = $d->{pkg};
  my $prod=0; my $test=0;
  my @sites;
  for my $path (keys %file_text) {
    my $text = $file_text{$path};
    my $fpkg = $file_pkg{$path};
    my $n = 0;
    if ($fpkg eq $pkg) {
      $n = count_matches($text, qr/(?<![\w.])$name\s*\(/);
      $n -= count_matches($text, qr/^func\s+$name\s*\(/m);
    } else {
      $n = count_matches($text, qr/\b$pkg\.$name\s*\(/);
    }
    $n = 0 if $n < 0;
    next unless $n;
    if ($file_is_test{$path}) { $test += $n; } else { $prod += $n; }
    push @sites, "$n $path" if $n;
  }
  push @funcs, {d=>$d, prod=>$prod, test=>$test, total=>$prod+$test, sites=>\@sites};
}
@funcs = sort { $b->{total} <=> $a->{total} || $b->{prod} <=> $a->{prod} } @funcs;
for my $i (0..24) {
  my $r = $funcs[$i];
  my $d = $r->{d};
  printf "%2d. %s.%s prod=%d test=%d total=%d %s:%d\n",
    $i+1, $d->{pkg}, $d->{name}, $r->{prod}, $r->{test}, $r->{total}, $d->{path}, $d->{line};
}

print "\n=== DISTINCTIVE METHODS (name not in common set) ===\n";
my %common = map { $_=>1 } qw(Next Len Parse Validate Kind Field Stop Start Register Compile Render Send New Close Swap Less String Error Type Name Get Set Write Read Reset String Value Done);
my @meths;
for my $d (@decls) {
  next unless $d->{is_method};
  next if $common{$d->{name}};
  my $name = $d->{name};
  my $pkg = $d->{pkg};
  my $prod=0; my $test=0;
  for my $path (keys %file_text) {
    my $text = $file_text{$path};
    my $n = count_matches($text, qr/\.$name\s*\(/);
    next unless $n;
    # subtract declaration
    if ($path eq $d->{path}) {
      $n -= count_matches($text, qr/^func\s+\([^)]+\)\s+$name\s*\(/m);
    }
    $n = 0 if $n < 0;
    if ($file_is_test{$path}) { $test += $n; } else { $prod += $n; }
  }
  push @meths, {d=>$d, prod=>$prod, test=>$test, total=>$prod+$test};
}
@meths = sort { $b->{total} <=> $a->{total} || $b->{prod} <=> $a->{prod} } @meths;
for my $i (0..24) {
  my $r = $meths[$i];
  my $d = $r->{d};
  printf "%2d. %s.%s prod=%d test=%d total=%d recv=[%s] %s:%d\n",
    $i+1, $d->{pkg}, $d->{name}, $r->{prod}, $r->{test}, $r->{total}, $d->{recv}, $d->{path}, $d->{line};
}
'
